"Последнюю цифру суммы даёт разряд единиц: 1 + 0 = 1, в единицах пишем 1. Всё число: 81 361": "Yigʻindining oxirgi raqamini birlar xonasi beradi: 1 + 0 = 1, birlarda 1 yozamiz. Butun son: 81 361",
