"Площадь всего прямоугольника: 15 · 6 = 90 м². Площадь выреза: 4 · 2 = 8 м². 90 − 8 = 82 м².": "Butun toʻgʻri toʻrtburchak yuzi: 15 · 6 = 90 m². Kesilgan qism yuzi: 4 · 2 = 8 m². 90 − 8 = 82 m².",
"В магазине предлагают: 750 тг за 3 кг мандаринов или 850 тг за 5 кг. Где мандарины дешевле?": "Doʻkonda taklif qilishadi: 3 kg mandarin 750 tg yoki 5 kg 850 tg. Mandarin qayerda arzonroq?",
"В магазине предлагают: 750 тг за 3 кг мандаринов или 850 тг за 5 кг. Где мандарины дешевле?": "Doʻkonda taklif qilishadi: 3 kg mandarin 750 tg yoki 5 kg 850 tg. Mandarin qayerda arzonroq?",
"Если из суммы вычесть одно слагаемое, получится другое. Например, 12 + 5 = 17, а 17 − 5 = 12": "Agar yigʻindidan bitta qoʻshiluvchini ayirsak, ikkinchisi chiqadi. Masalan, 12 + 5 = 17, 17 − 5 = 12",
