"От школы до дома 1 360 м. Тимур идёт со скоростью 80 м/мин. За сколько минут он дойдёт до дома?": "Maktabdan uygacha 1 360 m. Timur 80 m/daq tezlik bilan yuradi. U uyga necha daqiqada yetib boradi?",
"От школы до дома 1 360 м. Тимур идёт со скоростью 80 м/мин. За сколько минут он дойдёт до дома?": "Maktabdan uygacha 1 360 m. Timur 80 m/daq tezlik bilan yuradi. U uyga necha daqiqada yetib boradi?",
"Тех, кто занимается и тем и другим, при сложении посчитали дважды. 18 + 12 − 7 = 23. Ответ: 23.": "Ikkalasi bilan ham shugʻullanadiganlar qoʻshishda ikki marta sanaldi. 18 + 12 − 7 = 23. Javob: 23.",
"Наибольшая сумма в разряде: 9 + 9 + 1 = 19. Это 1 десяток и 9 единиц, значит переносим только 1.": "Xonadagi eng katta yigʻindi: 9 + 9 + 1 = 19. Bu 1 oʻnlik va 9 birlik, demak faqat 1 ni oʻtkazamiz.",
"Объём измеряют кубическими единицами: кубический сантиметр, кубический дециметр, кубический метр.": "Hajm kub birliklarda oʻlchanadi: kub santimetr, kub detsimetr, kub metr.",
"Считаем разряды справа: 7 — единицы, 0 — десятки, 2 — сотни, 5 — единицы тысяч, 8 — десятки тысяч.": "Xonalarni oʻngdan sanaymiz: 7 — birlar, 0 — oʻnlar, 2 — yuzlar, 5 — birlik minglar, 8 — oʻn minglar.",
"Если цена та же, а количество товара стало больше в 4 раза, стоимость тоже станет больше в 4 раза.": "Agar narx oʻsha-oʻsha boʻlib, tovar miqdori 4 marta koʻpaysa, qiymat ham 4 marta ortadi.",
"17 детей любят футбол, 11 — волейбол, 5 — и футбол, и волейбол. Сколько детей любят только футбол?": "17 bola futbolni, 11 tasi voleybolni, 5 tasi ham futbolni, ham voleybolni yaxshi koʻradi. Nechta bola faqat futbolni yaxshi koʻradi?",
