"Врач назначил по 250 мг лекарства 3 раза в день. Сколько граммов лекарства выпьет пациент за 8 дней?": "Shifokor kuniga 3 marta 250 mg dan dori buyurdi. Bemor 8 kunda necha gramm dori ichadi?",
"Круги Эйлера: «любят теннис» и «любят борьба». Аружан находится в пересечении кругов. Что это значит?": "Eyler doiralari: «tennisni yaxshi koʻradi» va «kurashni yaxshi koʻradi». Aruzhan doiralar kesishmasida. Bu nimani bildiradi?",
