"Выполнять действия с многозначными числами, находить неизвестный компонент в уравнении и решать задачи": "Koʻp xonali sonlar bilan amallar bajarish, tenglamada nomaʼlum komponentni topish va masalalar yechish",
"Справа налево: единицы, десятки, сотни — это нули, потом нуль в единицах тысяч, а 5 — в десятках тысяч.": "Oʻngdan chapga: birlar, oʻnlar, yuzlar — bular nollar, keyin birlik minglarda nol, 5 esa — oʻn minglarda.",
"Аквариум: длина 8 дм, ширина 4 дм, высота 4 дм. Сколько литров воды нужно, чтобы налить его наполовину?": "Akvarium: uzunligi 8 dm, kengligi 4 dm, balandligi 4 dm. Uni yarmigacha toʻldirish uchun necha litr suv kerak?",
"Аквариум: длина 8 дм, ширина 4 дм, высота 4 дм. Сколько литров воды нужно, чтобы налить его наполовину?": "Akvarium: uzunligi 8 dm, kengligi 4 dm, balandligi 4 dm. Uni yarmigacha toʻldirish uchun necha litr suv kerak?",
"Второе слагаемое = сумма − известное слагаемое: 108 705 − 107 192 = 1 513. Это и есть проверка вычитанием": "Ikkinchi qoʻshiluvchi = yigʻindi − maʼlum qoʻshiluvchi: 108 705 − 107 192 = 1 513. Bu ayirish bilan tekshirishning oʻzi",
"Второе слагаемое = сумма − известное слагаемое: 108 705 − 107 192 = 1 513. Это и есть проверка вычитанием": "Ikkinchi qoʻshiluvchi = yigʻindi − maʼlum qoʻshiluvchi: 108 705 − 107 192 = 1 513. Bu ayirish bilan tekshirishning oʻzi",
"Делим по очереди: 96 : 4 = 24, 24 : 2 = 12. Если делитель увеличить в 2 раза, частное уменьшится в 2 раза.": "Navbatma-navbat boʻlamiz: 96 : 4 = 24, 24 : 2 = 12. Agar boʻluvchi 2 marta oshsa, boʻlinma 2 marta kamayadi.",
"Класс миллионов — 105, класс тысяч — 300, класс единиц — 012. Нули нужны, чтобы цифры встали на свои места.": "Millionlar sinfi — 105, minglar sinfi — 300, birliklar sinfi — 012. Raqamlar oʻz joyiga tushishi uchun nollar kerak.",
"Чтобы сравнить площади, переводим их в одну единицу. Пример: 5 а и 450 м²: 5 а = 500 м², а 500 м² > 450 м².": "Yuzalarni solishtirish uchun ularni bir birlikka aylantiramiz. Misol: 5 ar va 450 m²: 5 ar = 500 m², 500 m² > 450 m².",
"На 2 делятся числа, которые оканчиваются на 0, 2, 4, 6, 8. 3 729 оканчивается на 9, значит, на 2 не делится.": "2 ga oxiri 0, 2, 4, 6, 8 bilan tugaydigan sonlar boʻlinadi. 3 729 soni 9 bilan tugaydi, demak, 2 ga boʻlinmaydi.",
"На 2 делятся числа, которые оканчиваются на 0, 2, 4, 6, 8. 3 729 оканчивается на 9, значит, на 2 не делится.": "2 ga oxiri 0, 2, 4, 6, 8 bilan tugaydigan sonlar boʻlinadi. 3 729 soni 9 bilan tugaydi, demak, 2 ga boʻlinmaydi.",
