"При делении на 1 000 справа отбрасываем три нуля. 51 000 : 1 000 = 51.": "1 000 ga boʻlganda oʻng tomondan uchta nolni tashlaymiz. 51 000 : 1 000 = 51.",
"При делении на 1 000 справа отбрасываем три нуля. 51 000 : 1 000 = 51.": "1 000 ga boʻlganda oʻng tomondan uchta nolni tashlaymiz. 51 000 : 1 000 = 51.",
"Число разделили на 8 и получили 2 508 без остатка. Какое число делили?": "Son 8 ga boʻlindi va qoldiqsiz 2 508 chiqdi. Qaysi son boʻlingan?",
"Число разделили на 8 и получили 2 508 без остатка. Какое число делили?": "Son 8 ga boʻlindi va qoldiqsiz 2 508 chiqdi. Qaysi son boʻlingan?",
"Так считать нельзя. Нужно занять 1 единицу у соседнего старшего разряда": "Bunday hisoblab boʻlmaydi. Qoʻshni katta xonadan 1 birlik qarz olish kerak",
"число уменьшили в 100 раз — разделили на 100, справа отбросили два нуля": "son 100 marta kamaytirildi — 100 ga boʻlindi, oʻng tomondan ikkita nol tashlandi",
"Какую цифру надо поставить вместо *, чтобы число 1 387* делилось на 10?": "1 387* soni 10 ga boʻlinishi uchun * oʻrniga qaysi raqamni qoʻyish kerak?",
"Какую цифру надо поставить вместо *, чтобы число 1 387* делилось на 10?": "1 387* soni 10 ga boʻlinishi uchun * oʻrniga qaysi raqamni qoʻyish kerak?",
"Нет разряда — считаем в нём 0. Разряды при этом остаются на своих местах": "Xona yoʻq — unda 0 deb hisoblaymiz. Xonalar oʻz joyida qoladi",
"Спринтер бежит со скоростью 7 м/с. За сколько секунд он преодолеет 84 м?": "Sprinter 7 m/s tezlikda yuguradi. U 84 m ni necha sekundda bosib oʻtadi?",
"Так считать нельзя. Нужно занять 1 единицу у соседнего старшего разряда.": "Bunday hisoblab boʻlmaydi. Qoʻshni katta xonadan 1 birlik qarz olish kerak.",
"Результат деления называют частным, например 56 : 8 = 7, где 7 — частное.": "Boʻlish natijasi boʻlinma deyiladi, masalan 56 : 8 = 7, bunda 7 — boʻlinma.",
"Неверно: на 4 нужно делить каждое слагаемое. (40 + 20) : 4 = 10 + 5 = 15.": "Notoʻgʻri: 4 ga har bir qoʻshiluvchini boʻlish kerak. (40 + 20) : 4 = 10 + 5 = 15.",
"При сложении числа элементов двух множеств общие элементы считают дважды.": "Ikki toʻplam elementlari sonini qoʻshganda umumiy elementlar ikki marta sanaladi.",
"Оканчивается на 5 — делится на 5. Но на 2 и на 10 такие числа не делятся.": "5 bilan tugaydi — 5 ga boʻlinadi. Lekin bunday sonlar 2 ga va 10 ga boʻlinmaydi.",
"Чтобы найти неизвестное вычитаемое, надо к разности прибавить уменьшаемое.": "Nomaʼlum ayriluvchini topish uchun ayirmaga kamayuvchini qoʻshish kerak.",
"До школы 900 м. Арман проходит 60 м за минуту. За сколько минут он дойдёт?": "Maktabgacha 900 m. Arman minutiga 60 m yuradi. U necha minutda yetib boradi?",
"В делителе 3 нуля, значит, отделяем три цифры. Отделённые цифры — остаток.": "Boʻluvchida 3 ta nol bor, demak, uchta raqamni ajratamiz. Ajratilgan raqamlar — qoldiq.",
"Разность равна 33 654, вычитаемое — 32 738, тогда уменьшаемое равно 66 392.": "Ayirma 33 654 ga teng, ayriluvchi — 32 738, unda kamayuvchi 66 392 ga teng.",
"Разность равна 33 654, вычитаемое — 32 738, тогда уменьшаемое равно 66 392.": "Ayirma 33 654 ga teng, ayriluvchi — 32 738, unda kamayuvchi 66 392 ga teng.",
"Самолёт летит со скоростью 800 км/ч. Сколько километров он пролетит за 3 ч?": "Samolyot 800 km/soat tezlikda uchadi. U 3 soatda necha kilometr uchadi?",
"Общие элементы — это пересечение. Объединение — все элементы из A или из B.": "Umumiy elementlar — bu kesishma. Birlashma — A dagi yoki B dagi barcha elementlar.",
"Повторить задачи на движение, действия с множествами, объём и площадь фигур": "Harakatga oid masalalar, toʻplamlar ustida amallar, shakllarning hajmi va yuzini takrorlash",
"Круги Эйлера: «делятся на 2» и «делятся на 5». Где нужно записать число 825?": "Eyler doiralari: «2 ga boʻlinadi» va «5 ga boʻlinadi». 825 sonini qayerga yozish kerak?",
"Мелких единиц получается больше, поэтому умножаем. Например, 4 г = 4 000 мг.": "Mayda birliklar koʻproq chiqadi, shuning uchun koʻpaytiramiz. Masalan, 4 g = 4 000 mg.",
"Чтобы найти неизвестное слагаемое, надо из суммы вычесть известное слагаемое.": "Nomaʼlum qoʻshiluvchini topish uchun yigʻindidan maʼlum qoʻshiluvchini ayirish kerak.",
"Общие элементы считаем один раз: 3 + 4 − 2 = 5. Объединение: {Т, О, Б, К, Е}.": "Umumiy elementlarni bir marta sanaymiz: 3 + 4 − 2 = 5. Birlashma: {T, O, B, K, E}.",
"Разность двух чисел равна 6 198, вычитаемое — 35 746. Чему равно уменьшаемое?": "Ikki son ayirmasi 6 198 ga teng, ayriluvchi — 35 746. Kamayuvchi nimaga teng?",
"Разность двух чисел равна 6 198, вычитаемое — 35 746. Чему равно уменьшаемое?": "Ikki son ayirmasi 6 198 ga teng, ayriluvchi — 35 746. Kamayuvchi nimaga teng?",
"Автобус едет со скоростью 50 км/ч. Какое расстояние он преодолеет за 9 часов?": "Avtobus 50 km/soat tezlikda ketmoqda. U 9 soatda qancha masofani bosib oʻtadi?",
"Автобус едет со скоростью 50 км/ч. Какое расстояние он преодолеет за 9 часов?": "Avtobus 50 km/soat tezlikda ketmoqda. U 9 soatda qancha masofani bosib oʻtadi?",
