"Из прямоугольника 15 м × 8 м вырезали прямоугольник 2 м × 4 м. Осталось 112 м².": "15 m × 8 m li toʻgʻri toʻrtburchakdan 2 m × 4 m li toʻgʻri toʻrtburchak kesib olindi. 112 m² qoldi.",
"Из прямоугольника 15 м × 8 м вырезали прямоугольник 2 м × 4 м. Осталось 112 м².": "15 m × 8 m li toʻgʻri toʻrtburchakdan 2 m × 4 m li toʻgʻri toʻrtburchak kesib olindi. 112 m² qoldi.",
"Как выполнить действие с величинами в разных единицах, например 2 га − 2 000 м²?": "Turli birliklardagi kattaliklar ustida amalni qanday bajarish kerak, masalan 2 ga − 2 000 m²?",
