"Миллиграмм (мг) — меньшая единица измерения массы. В одном грамме 1 000 миллиграммов": "Milligramm (mg) — massaning kichikroq oʻlchov birligi. Bir grammda 1 000 milligramm bor",
"Привет! Это Барсик. Сегодня учимся измерять объём тел кубиками. Нажимай на карточки.": "Salom! Men Barsikman. Bugun jismlarning hajmini kubiklar bilan oʻlchashni oʻrganamiz. Kartochkalarni bos.",
"Каждое число больше предыдущего на 10 000. Следующее число: 35 000 + 10 000 = 45 000.": "Har bir son oldingisidan 10 000 ga katta. Keyingi son: 35 000 + 10 000 = 45 000.",
"Объём измеряют в кубических единицах: см³, дм³, м³. Квадратные единицы — для площади.": "Hajm kub birliklarda oʻlchanadi: sm³, dm³, m³. Kvadrat birliklar — yuza uchun.",
