"Одна машина едет за другой со скоростями 90 км/ч и 70 км/ч. Какова скорость сближения?": "Bir mashina ikkinchisining ketidan 90 km/soat va 70 km/soat tezlikda ketmoqda. Yaqinlashish tezligi qancha?",
