"В 1 м³ содержится 1 000 дм³. 2 000 : 1 000 = 2. Значит, 2 000 дм³ = 2 м³.": "1 m³ da 1 000 dm³ bor. 2 000 : 1 000 = 2. Demak, 2 000 dm³ = 2 m³.",
