"Как найти скорость удаления, если тела движутся в противоположные стороны?": "Jismlar qarama-qarshi tomonlarga harakatlansa, uzoqlashish tezligini qanday topish mumkin?",
"Расстояние между ними сокращается, они выехали из разных мест друг к другу": "Ular orasidagi masofa qisqaryapti, ular turli joylardan bir-biriga qarab yoʻlga chiqqan",
"8 · 7 = 56. Единицы пишем под чертой, десятки переносим в следующий разряд.": "8 · 7 = 56. Birlarni chiziq ostiga yozamiz, oʻnlarni keyingi xonaga oʻtkazamiz.",
"Они удаляются друг от друга обоими движениями, поэтому скорости складываем.": "Ular ikkala harakat bilan bir-biridan uzoqlashadi, shuning uchun tezliklarni qoʻshamiz.",
"Это единица объёма. Площадь измеряют в квадратных единицах, например в см².": "Bu hajm birligi. Yuza kvadrat birliklarda oʻlchanadi, masalan, sm² da.",
"Раздели число на классы по три цифры справа налево. Третий класс — миллионы.": "Sonni oʻngdan chapga uchtadan raqamli sinflarga ajrat. Uchinchi sinf — millionlar.",
